import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"C ABI reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/c-abi.md","filePath":"reference/c-abi.md"}'),c={name:"reference/c-abi.md"};function a(n,e,s,l,i,u){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="c-abi-reference" tabindex="-1">C ABI reference <a class="header-anchor" href="#c-abi-reference" aria-label="Permalink to &quot;C ABI reference&quot;">​</a></h1><p>Version <code>MUMBLE_ABI_VERSION</code> = <strong>2</strong> (<code>mumble_abi_version()</code> returns it at run time). Version 2 replaced the per-event dot (color and size) with the sound identifier.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to &quot;Rules&quot;">​</a></h2><ul><li>Every function that can fail returns <code>int32_t</code>: <code>MUMBLE_OK</code> (0) or a negative code. On error, output parameters are left untouched.</li><li>No Rust panic crosses the boundary: it becomes <code>MUMBLE_ERR_PANIC</code>.</li><li>Text is <code>(const char *utf8, size_t len)</code>, not NUL-terminated. <code>utf8</code> may be <code>NULL</code> when <code>len</code> is 0.</li><li>Objects are opaque and owned by the caller; <code>*_free</code> functions accept <code>NULL</code>.</li></ul><h2 id="error-codes" tabindex="-1">Error codes <a class="header-anchor" href="#error-codes" aria-label="Permalink to &quot;Error codes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Name</th><th>Meaning</th></tr></thead><tbody><tr><td>0</td><td><code>MUMBLE_OK</code></td><td>Success</td></tr><tr><td>−1</td><td><code>MUMBLE_ERR_NULL</code></td><td>A required pointer is <code>NULL</code></td></tr><tr><td>−2</td><td><code>MUMBLE_ERR_UTF8</code></td><td>Text is not valid UTF-8</td></tr><tr><td>−3</td><td><code>MUMBLE_ERR_VOICE</code></td><td>Voice out of range or unknown style</td></tr><tr><td>−4</td><td><code>MUMBLE_ERR_SAMPLE_RATE</code></td><td>Sample rate outside 8,000–192,000 Hz</td></tr><tr><td>−5</td><td><code>MUMBLE_ERR_INDEX</code></td><td>Event index out of range</td></tr><tr><td>−99</td><td><code>MUMBLE_ERR_PANIC</code></td><td>Internal error caught at the boundary</td></tr></tbody></table><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Fields</th></tr></thead><tbody><tr><td><code>MumbleVoice</code></td><td><code>style</code> (0 beep, 1 grunt, 2 alphabet), <code>pitch</code>, <code>speed</code>, <code>variation</code>, <code>seed</code></td></tr><tr><td><code>MumbleEvent</code></td><td><code>grapheme_index</code>, <code>utf8_start</code>, <code>utf8_len</code>, <code>utf16_start</code>, <code>utf16_len</code>, <code>start</code>, <code>duration</code>, <code>style</code>, <code>variant</code></td></tr><tr><td><code>MumbleUtterance</code></td><td><code>samples</code> (valid until the next call on the speaker or its free), <code>sample_count</code>, <code>advance</code>, <code>style</code>, <code>variant</code>, <code>has_sound</code></td></tr><tr><td><code>MumbleRender</code>, <code>MumbleSpeaker</code></td><td>opaque</td></tr></tbody></table><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>mumble_abi_version()</code></td><td>ABI version of the loaded library.</td></tr><tr><td><code>mumble_render(utf8, len, voice, sample_rate, &amp;render)</code></td><td>Renders a line.</td></tr><tr><td><code>mumble_render_samples(render, &amp;len)</code></td><td>Mono <code>float</code> samples, valid until <code>mumble_render_free</code>.</td></tr><tr><td><code>mumble_render_duration(render)</code></td><td>Seconds: end of the last sound plus 50 ms.</td></tr><tr><td><code>mumble_render_event_count(render)</code>, <code>mumble_render_event(render, i, &amp;event)</code></td><td>Events.</td></tr><tr><td><code>mumble_render_free(render)</code></td><td>Frees a render.</td></tr><tr><td><code>mumble_speaker_new(voice, sample_rate, &amp;speaker)</code></td><td>Typewriter speaker.</td></tr><tr><td><code>mumble_speaker_next(speaker, utf8, len, &amp;utterance)</code></td><td>Sound of the next character(s).</td></tr><tr><td><code>mumble_speaker_reset(speaker)</code>, <code>mumble_speaker_free(speaker)</code></td><td>Reset, free.</td></tr><tr><td><code>mumble_encode_wav(samples, len, sample_rate, &amp;bytes, &amp;bytes_len)</code></td><td>16-bit PCM mono WAV.</td></tr><tr><td><code>mumble_bytes_free(bytes, bytes_len)</code></td><td>Frees WAV bytes.</td></tr></tbody></table>',10)])])}const b=t(c,[["render",a]]);export{m as __pageData,b as default};
